 if(kind==='equipment'){body=readValue('Equipment Name',d.name)+readValue('Equipment Type',d.equipmentType)+readValue('Category',d.category)+readValue('Cost',d.cost)+readValue(d.edition==='N26'?'Trade Points':'Availability',d.edition==='N26'?d.tradePoints:d.availability)+readValue('Description',d.description,'wide');if(d.equipmentType==='Weapon'){const n26=d.edition==='N26';body+=group('Weapon Profiles',d.weaponProfiles.length?d.weaponProfiles.map(p=>`<div class="ap-read-profile"><span><strong>Name:</strong> ${esc(p.profile_name)}</span><span><strong>Range:</strong> ${esc(p.range_short)} / ${esc(p.range_long)}</span>${n26?'':`<span><strong>Accuracy:</strong> ${esc(p.acc_short)} / ${esc(p.acc_long)}</span>`}<span><strong>Strength:</strong> ${esc(p.strength)}</span><span><strong>AP:</strong> ${esc(p.ap)}</span>${n26?`<span><strong>Lethality:</strong> ${esc(p.lethality)}</span>`:`<span><strong>Damage:</strong> ${esc(p.damage)}</span><span><strong>Ammo:</strong> ${esc(p.ammo)}</span>`}<span><strong>Traits:</strong> ${traitMarkup(p.traits,d.edition)}</span></div>`).join(''):'<p class="ap-read-value">No weapon profiles defined</p>');}}
